/*
 Problem: 3302. Find the Lexicographically Smallest Valid Sequence
 Language: cpp
 Runtime: 51 ms (31.95%)
 Memory: 114.5 MB (48.74%)
 Tags: Two Pointers, String, Dynamic Programming, Greedy
*/
class Solution {
public:
    vector<int> validSequence(string s, string t) {
        int n = s.size(), m = t.size();
        vector<int> suf(n + 1);

        for (int i = n - 1, j = m - 1; i >= 0; --i) {
            suf[i] = suf[i + 1];
            if (j >= 0 && s[i] == t[j])
                ++suf[i], --j;
        }

        vector<int> ans(m);
        int i = 0, j = 0;

        while (i < n && j < m) {
            if (s[i] == t[j]) {
                ans[j++] = i++;
            } else if (suf[i + 1] >= m - j - 1) {
                ans[j++] = i++;
                break;
            } else {
                ++i;
            }
        }

        while (i < n && j < m) {
            if (s[i] == t[j])
                ans[j++] = i;
            ++i;
        }

        return j == m ? ans : vector<int>{};
    }
};
